function e(e,t,n){return[e[0]+(t[0]-e[0])*n,e[1]+(t[1]-e[1])*n]}function t(t){let n=[t[0]];for(let r=0;r<t.length;r++){let i=t[r],a=t[(r+1)%t.length];for(let t=0;t<2;t++){let r=t/2,o=(t+1)/2,s=e(i,a,r),c=e(i,a,o);n.push(e(s,c,1/3),e(s,c,2/3),c)}}return n}function n(e,n){return t([e,n,n,e])}function r(e,n,r,i){return t([[e,n],[e+r,n],[e+r,n+i],[e,n+i]])}function i(e){if(e.length<4||(e.length-1)%3!=0)throw Error(`A cubic loop needs 1+3n points`);let t=e=>Math.round(e*1e3)/1e3,n=`M${t(e[0][0])} ${t(e[0][1])}`;for(let r=1;r<e.length;r+=3)n+=`C${t(e[r][0])} ${t(e[r][1])} ${t(e[r+1][0])} ${t(e[r+1][1])} ${t(e[r+2][0])} ${t(e[r+2][1])}`;return`${n}Z`}function a(e,t){let n=[...e].sort((e,t)=>e.at-t.at),r=n.length,i=n.length?Math.max(0,n[0].at):t;for(let e=0;e<n.length;e++){let r=n[e].at+n[e].duration,a=n[e+1]?.at??t;i=Math.max(i,Math.max(0,a-r))}let a=r/Math.max(t,.001)*10;return{starts:r,startsPer10s:Math.round(a*100)/100,opsPer10s:Math.round(a*100)/100,maxHold:Math.round(i*100)/100,passes:a>=2&&i<=2.5}}export{r as i,a as n,i as r,n as t};